export interface ConnectorConfig {
  /** Stripe secret API key (sk_live_... or sk_test_...). */
  stripeApiKey: string;
  /** HubSpot private app API key or OAuth access token for CRM API calls. */
  hubspotApiKey: string;
  /** Base URL for HubSpot CRM API. Defaults to 'https://api.hubapi.com'. */
  hubspotBaseUrl?: string;
  /** Injected fetch implementation (tests provide a fake). */
  fetch: typeof fetch;
}

export interface HubSpotWebhookPayload {
  subscriptionType: string;
  propertyName: string;
  propertyValue: string;
  objectId: string;
  eventId: string;
  occurredAt: number;
  portalId: string;
  appId: string;
}

export interface HubSpotContact {
  id: string;
  properties: {
    email?: string;
    firstname?: string;
    lastname?: string;
    lifecyclestage?: string;
  };
}

export interface StripeCustomerResponse {
  id: string;
  object: string;
  email: string;
  name: string;
  created: number;
  livemode: boolean;
}

export interface HandleResult {
  stripeCustomerId: string;
  hubspotContactId: string;
}

function validatePayload(payload: unknown): asserts payload is HubSpotWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object');
  }
  const p = payload as Record<string, unknown>;
  const required = ['subscriptionType', 'propertyName', 'propertyValue', 'objectId', 'eventId', 'occurredAt', 'portalId', 'appId'];
  for (const field of required) {
    if (p[field] === undefined || p[field] === null || p[field] === '') {
      throw new Error(`Missing required field: ${field}`);
    }
  }
  if (p.subscriptionType !== 'contact.propertyChange') {
    throw new Error(`Unexpected subscriptionType: ${p.subscriptionType}`);
  }
  if (p.propertyName !== 'lifecyclestage') {
    throw new Error(`Unexpected propertyName: ${p.propertyName}`);
  }
  if (p.propertyValue !== 'customer') {
    throw new Error(`Lifecycle stage is not 'customer': ${p.propertyValue}`);
  }
}

async function fetchHubSpotContact(config: ConnectorConfig, contactId: string): Promise<HubSpotContact> {
  const baseUrl = config.hubspotBaseUrl ?? 'https://api.hubapi.com';
  const url = `${baseUrl}/crm/v3/objects/contacts/${contactId}?properties=email,firstname,lastname,lifecyclestage`;
  const response = await config.fetch(url, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${config.hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`HubSpot CRM API error: ${response.status} ${response.statusText} for GET ${url}`);
  }
  const data = await response.json() as HubSpotContact;
  return data;
}

function buildName(firstname?: string, lastname?: string): string {
  const parts = [firstname?.trim(), lastname?.trim()].filter(Boolean);
  return parts.join(' ') || '';
}

async function createStripeCustomer(config: ConnectorConfig, email: string, name: string): Promise<StripeCustomerResponse> {
  const url = 'https://api.stripe.com/v1/customers';
  const body = new URLSearchParams();
  body.append('email', email);
  if (name) {
    body.append('name', name);
  }
  const response = await config.fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.stripeApiKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} for POST ${url}: ${text}`);
  }
  return response.json() as Promise<StripeCustomerResponse>;
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload);
  const webhook = payload as HubSpotWebhookPayload;
  const contact = await fetchHubSpotContact(config, webhook.objectId);
  if (contact.properties.lifecyclestage !== 'customer') {
    throw new Error(`Contact ${contact.id} lifecycle stage is not 'customer': ${contact.properties.lifecyclestage}`);
  }
  const email = contact.properties.email?.trim();
  if (!email) {
    throw new Error(`Contact ${contact.id} has no email address`);
  }
  const name = buildName(contact.properties.firstname, contact.properties.lastname);
  const stripeCustomer = await createStripeCustomer(config, email, name);
  return {
    stripeCustomerId: stripeCustomer.id,
    hubspotContactId: contact.id,
  };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handle, ConnectorConfig, HubSpotWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      stripeApiKey: 'sk_test_123',
      hubspotApiKey: 'hubspot_test_key',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib');
    expect(result.hubspotContactId).toBe('123456');
  });
});

describe('handle', () => {
  let baseConfig: ConnectorConfig;
  let fetchMock: typeof fetch;
  let calls: { method: string; url: string; body: string | undefined; json: unknown; headers: Headers }[];

  beforeEach(() => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({
          id: '123456',
          properties: {
            email: 'jennyrosen@example.com',
            firstname: 'Jenny',
            lastname: 'Rosen',
            lifecyclestage: 'customer',
          },
        });
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    fetchMock = fake.fetch;
    calls = fake.calls;
    baseConfig = {
      stripeApiKey: 'sk_test_123',
      hubspotApiKey: 'hubspot_test_key',
      fetch: fetchMock,
    };
  });

  it('happy path: fetches contact and creates Stripe customer with combined name', async () => {
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: '01H8X7Y5Z7J6K5T4R3Q2P1O0N9M8L7K6',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    const result = await handle(payload, baseConfig);
    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib');
    expect(result.hubspotContactId).toBe('123456');
    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[0].url).toContain('/crm/v3/objects/contacts/123456');
    expect(calls[0].headers.get('authorization')).toBe('Bearer hubspot_test_key');
    expect(calls[1].method).toBe('POST');
    expect(calls[1].url).toBe('https://api.stripe.com/v1/customers');
    expect(calls[1].headers.get('authorization')).toBe('Bearer sk_test_123');
    expect(calls[1].headers.get('content-type')).toBe('application/x-www-form-urlencoded');
    const body = calls[1].body as string;
    expect(body).toContain('email=jennyrosen%40example.com');
    expect(body).toContain('name=Jenny+Rosen');
  });

  it('uses only firstname when lastname is missing', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({
          id: '123456',
          properties: {
            email: 'john@example.com',
            firstname: 'John',
            lastname: '',
            lifecyclestage: 'customer',
          },
        });
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ ...TARGET_ENDPOINTS[0].response, id: 'cus_test', name: 'John', email: 'john@example.com' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch: fake.fetch };
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: 'evt1',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    const result = await handle(payload, config);
    expect(result.stripeCustomerId).toBe('cus_test');
    const stripeCall = fake.calls.find(c => c.url === 'https://api.stripe.com/v1/customers');
    expect(stripeCall).toBeDefined();
    const body = stripeCall!.body as string;
    expect(body).toContain('name=John');
    expect(body).not.toContain('name=John+');
  });

  it('uses only lastname when firstname is missing', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({
          id: '123456',
          properties: {
            email: 'doe@example.com',
            firstname: '',
            lastname: 'Doe',
            lifecyclestage: 'customer',
          },
        });
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ ...TARGET_ENDPOINTS[0].response, id: 'cus_test2', name: 'Doe', email: 'doe@example.com' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch: fake.fetch };
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: 'evt2',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    const result = await handle(payload, config);
    expect(result.stripeCustomerId).toBe('cus_test2');
    const stripeCall = fake.calls.find(c => c.url === 'https://api.stripe.com/v1/customers');
    const body = stripeCall!.body as string;
    expect(body).toContain('name=Doe');
  });

  it('throws when required field subscriptionType is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, subscriptionType: undefined };
    await expect(handle(payload as unknown as HubSpotWebhookPayload, baseConfig)).rejects.toThrow('Missing required field: subscriptionType');
  });

  it('throws when propertyValue is not customer', async () => {
    const payload = { ...SOURCE_EXAMPLE, propertyValue: 'lead' };
    await expect(handle(payload as unknown as HubSpotWebhookPayload, baseConfig)).rejects.toThrow("Lifecycle stage is not 'customer': lead");
  });

  it('throws when HubSpot contact fetch fails with non-2xx', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({ error: 'unauthorized' }, 401);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch: fake.fetch };
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: 'evt3',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    await expect(handle(payload, config)).rejects.toThrow('HubSpot CRM API error: 401 Unauthorized for GET');
  });

  it('throws when Stripe API returns non-2xx', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({
          id: '123456',
          properties: { email: 'test@example.com', firstname: 'Test', lastname: 'User', lifecyclestage: 'customer' },
        });
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        return jsonResponse({ error: { message: 'Invalid email' } }, 400);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch: fake.fetch };
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: 'evt4',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    await expect(handle(payload, config)).rejects.toThrow('Stripe API error: 400 Bad Request for POST https://api.stripe.com/v1/customers');
  });

  it('throws when contact has no email', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({
          id: '123456',
          properties: { firstname: 'Test', lastname: 'User', lifecyclestage: 'customer' },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch: fake.fetch };
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: 'evt5',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    await expect(handle(payload, config)).rejects.toThrow('Contact 123456 has no email address');
  });

  it('throws when contact lifecycle stage is not customer', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/contacts/123456')) {
        return jsonResponse({
          id: '123456',
          properties: { email: 'test@example.com', firstname: 'Test', lastname: 'User', lifecyclestage: 'subscriber' },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch: fake.fetch };
    const payload: HubSpotWebhookPayload = {
      subscriptionType: 'contact.propertyChange',
      propertyName: 'lifecyclestage',
      propertyValue: 'customer',
      objectId: '123456',
      eventId: 'evt6',
      occurredAt: 1717020800000,
      portalId: '62515',
      appId: '12345',
    };
    await expect(handle(payload, config)).rejects.toThrow("Contact 123456 lifecycle stage is not 'customer': subscriber");
  });
});

# HubSpot Contact to Stripe Customer Connector

Creates a Stripe customer record when a HubSpot contact's lifecycle stage changes to `customer`.

## What it does

1. Receives a HubSpot contact property change webhook (POST to your configured endpoint).
2. Validates the webhook payload: must be a `contact.propertyChange` for `lifecyclestage` becoming `customer`.
3. Fetches the full contact details from HubSpot CRM API using the `objectId` from the webhook.
4. Verifies the contact's `lifecyclestage` is `customer` and that an email exists.
5. Creates a Stripe customer with:
   - `email` → contact's email
   - `name` → concatenation of `firstname` and `lastname` (whichever are present)
6. Returns the created Stripe customer ID and HubSpot contact ID.

## Configuration

| Config property | Environment variable | Required | Description |
|-----------------|---------------------|----------|-------------|
| `stripeApiKey` | `STRIPE_API_KEY` | Yes | Stripe secret key (`sk_live_...` or `sk_test_...`). |
| `hubspotApiKey` | `HUBSPOT_API_KEY` | Yes | HubSpot private app API key or OAuth access token for CRM API calls. |
| `hubspotBaseUrl` | `HUBSPOT_BASE_URL` | No | Base URL for HubSpot CRM API. Defaults to `https://api.hubapi.com`. |
| `fetch` | — | Yes (injected) | Fetch implementation. Tests provide a fake; production uses global `fetch`. |

## Usage example

```ts
import { handle, ConnectorConfig } from './connector';

const config: ConnectorConfig = {
  stripeApiKey: process.env.STRIPE_API_KEY!,
  hubspotApiKey: process.env.HUBSPOT_API_KEY!,
  fetch: globalThis.fetch,
};

app.post('/webhook/receive-hubspot-contact-change', async (req, res) => {
  try {
    const result = await handle(req.body, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error(err);
    res.status(400).json({ error: err.message });
  }
});
```

## Assumptions

- The HubSpot contact has a `lifecyclestage` property that triggers the webhook when it becomes `customer`.
- The contact has `firstname` and/or `lastname` properties populated; the connector combines them for the Stripe `name` field.
- The Stripe API key has permission to create customers.
- No duplicate customer check is performed; each trigger creates a new Stripe customer.
- HubSpot webhook signature verification (via `X-HubSpot-Signature` header) is handled upstream (e.g., by your HTTP framework middleware) and is not part of this connector.
- The connector uses `application/x-www-form-urlencoded` for the Stripe API call as required.

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://developers.hubspot.com/docs/api-reference/legacy/crm/objects/contacts/guide
// Source: https://docs.stripe.com/api/customers/create

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "subscriptionType": "contact.propertyChange",
  "propertyName": "lifecyclestage",
  "propertyValue": "customer",
  "objectId": "123456",
  "eventId": "01H8X7Y5Z7J6K5T4R3Q2P1O0N9M8L7K6",
  "occurredAt": 1717020800000,
  "portalId": "62515",
  "appId": "12345"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.stripe.com/v1/customers",
    "response": {
      "id": "cus_NffrFeUfNV2Hib",
      "object": "customer",
      "email": "jennyrosen@example.com",
      "name": "Jenny Rosen",
      "created": 1680893993,
      "livemode": false
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Stripe secret API key (sk_live_... or sk_test_...). */
  stripeApiKey: string;
  /** HubSpot private app API key or OAuth access token for CRM API calls. */
  hubspotApiKey: string;
  /** Base URL for HubSpot CRM API. Defaults to 'https://api.hubapi.com'. */
  hubspotBaseUrl?: string;
  /** Injected fetch implementation (tests provide a fake). */
  fetch: typeof fetch;
}

export interface HubSpotWebhookPayload {
  subscriptionType: string;
  propertyName: string;
  propertyValue: string;
  objectId: string;
  eventId: string;
  occurredAt: number;
  portalId: string;
  appId: string;
}

export interface HubSpotContact {
  id: string;
  properties: {
    email?: string;
    firstname?: string;
    lastname?: string;
    lifecyclestage?: string;
  };
}

export interface StripeCustomerResponse {
  id: string;
  object: string;
  email: string;
  name: string;
  created: number;
  livemode: boolean;
}

export interface HandleResult {
  stripeCustomerId: string;
  hubspotContactId: string;
}

function validatePayload(payload: unknown): asserts payload is HubSpotWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object');
  }
  const p = payload as Record<string, unknown>;
  const required = ['subscriptionType', 'propertyName', 'propertyValue', 'objectId', 'eventId', 'occurredAt', 'portalId', 'appId'];
  for (const field of required) {
    if (p[field] === undefined || p[field] === null || p[field] === '') {
      throw new Error(`Missing required field: ${field}`);
    }
  }
  if (p.subscriptionType !== 'contact.propertyChange') {
    throw new Error(`Unexpected subscriptionType: ${p.subscriptionType}`);
  }
  if (p.propertyName !== 'lifecyclestage') {
    throw new Error(`Unexpected propertyName: ${p.propertyName}`);
  }
  if (p.propertyValue !== 'customer') {
    throw new Error(`Lifecycle stage is not 'customer': ${p.propertyValue}`);
  }
}

async function fetchHubSpotContact(config: ConnectorConfig, contactId: string): Promise<HubSpotContact> {
  const baseUrl = config.hubspotBaseUrl ?? 'https://api.hubapi.com';
  const url = `${baseUrl}/crm/v3/objects/contacts/${contactId}?properties=email,firstname,lastname,lifecyclestage`;
  const response = await config.fetch(url, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${config.hubspotApiKey}`,
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`HubSpot CRM API error: ${response.status} ${response.statusText} for GET ${url}`);
  }
  const data = await response.json() as HubSpotContact;
  return data;
}

function buildName(firstname?: string, lastname?: string): string {
  const parts = [firstname?.trim(), lastname?.trim()].filter(Boolean);
  return parts.join(' ') || '';
}

async function createStripeCustomer(config: ConnectorConfig, email: string, name: string): Promise<StripeCustomerResponse> {
  const url = 'https://api.stripe.com/v1/customers';
  const body = new URLSearchParams();
  body.append('email', email);
  if (name) {
    body.append('name', name);
  }
  const response = await config.fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.stripeApiKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} for POST ${url}: ${text}`);
  }
  return response.json() as Promise<StripeCustomerResponse>;
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload);
  const webhook = payload as HubSpotWebhookPayload;
  const contact = await fetchHubSpotContact(config, webhook.objectId);
  if (contact.properties.lifecyclestage !== 'customer') {
    throw new Error(`Contact ${contact.id} lifecycle stage is not 'customer': ${contact.properties.lifecyclestage}`);
  }
  const email = contact.properties.email?.trim();
  if (!email) {
    throw new Error(`Contact ${contact.id} has no email address`);
  }
  const name = buildName(contact.properties.firstname, contact.properties.lastname);
  const stripeCustomer = await createStripeCustomer(config, email, name);
  return {
    stripeCustomerId: stripeCustomer.id,
    hubspotContactId: contact.id,
  };
}

